 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Object descriptors: (center row, center col, half extent), diamonds or singleton 2s.
    diamonds = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (g[r-1][c-1] == 2 and g[r-1][c+1] == 2 and
                g[r+1][c-1] == 2 and g[r+1][c+1] == 2):
                diamonds.add((r, c))
    objects = [(r, c, 1) for r, c in diamonds]
    # Other isolated 2 cells are point objects.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 2 and not any(abs(r-dr) <= 1 and abs(c-dc) <= 1 for dr, dc in diamonds):
                objects.append((r, c, 0))
    for i, (r, c, a) in enumerate(objects):
        for rr, cc, b in objects[i+1:]:
            if r == rr and c != cc:
                lo, hi = sorted((c, cc))
                start = lo + (a if c == lo else b) + 1
                end = hi - (b if c == lo else a)
                for x in range(start, end):
                    if g[r][x] == 0: g[r][x] = 1
            elif c == cc and r != rr:
                lo, hi = sorted((r, rr))
                start = lo + (a if r == lo else b) + 1
                end = hi - (b if r == lo else a)
                for y in range(start, end):
                    if g[y][c] == 0: g[y][c] = 1
    return g
"
}

