    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (g[r][c] == 0 and g[r - 1][c] == 2 and g[r + 1][c] == 2
                    and g[r][c - 1] == 2 and g[r][c + 1] == 2):
                crosses.append((r, c))

    arms = set()
    for r, c in crosses:
        arms.update(((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)))
    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] == 2 and (r, c) not in arms]
    objects = [(r, c, True) for r, c in crosses] + [(r, c, False) for r, c in points]

    for i, (r, c, is_cross) in enumerate(objects):
        for rr, cc, other_cross in objects[i + 1:]:
            if r == rr and c != cc:
                lo, hi = sorted((c, cc))
                low_cross = is_cross if c == lo else other_cross
                high_cross = other_cross if c == lo else is_cross
                start = lo + (2 if low_cross else 1)
                end = hi - (1 if high_cross else 0)
                for x in range(start, end):
                    if g[r][x] == 0:
                        g[r][x] = 1
            elif c == cc and r != rr:
                lo, hi = sorted((r, rr))
                low_cross = is_cross if r == lo else other_cross
                high_cross = other_cross if r == lo else is_cross
                start = lo + (2 if low_cross else 1)
                end = hi - (1 if high_cross else 0)
                for y in range(start, end):
                    if g[y][c] == 0:
                        g[y][c] = 1
    return g
